def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13
    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_budgets = []
    opp_emergency = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            opp_budgets.append(opp.get('budget', 0))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                opp_emergency += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    slots = max(1, int(supply / WATER_REQ))
    competitors = len(alive) + 1
    scarcity = competitors - slots

    highest_prev = max(prev_bids) if prev_bids else DAILY_SALARY * 0.75
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else DAILY_SALARY * 0.7
    rich_opp = max(opp_budgets) if opp_budgets else 0

    survival_mode = hp <= 3 or no_water >= 1
    critical_mode = hp <= 2 or no_water >= 2

    if critical_mode:
        bid = max(DAILY_SALARY * 1.15, highest_prev + 3.0)
    elif survival_mode:
        bid = max(DAILY_SALARY * 0.95, avg_prev + 2.0)
    else:
        if slots >= competitors:
            bid = DAILY_SALARY * 0.28
        elif scarcity <= 1:
            bid = DAILY_SALARY * 0.48
        elif scarcity == 2:
            bid = DAILY_SALARY * 0.62
        else:
            bid = DAILY_SALARY * 0.78

        if highest_prev >= DAILY_SALARY * 1.8:
            bid = min(bid, DAILY_SALARY * 0.42)
        elif highest_prev >= DAILY_SALARY * 1.45:
            bid = min(max(bid, DAILY_SALARY * 0.52), highest_prev - 10.0)
        elif highest_prev >= DAILY_SALARY * 1.1:
            bid = max(bid, highest_prev - 12.0)

    if opp_emergency >= 2 and not survival_mode:
        bid *= 0.88

    if rich_opp > budget * 1.8 and not survival_mode:
        bid *= 0.92

    if day >= 8 and hp >= 6 and no_water == 0 and not survival_mode:
        bid *= 0.9

    min_safe = 0.0
    if critical_mode:
        min_safe = DAILY_SALARY * 0.9
    elif survival_mode:
        min_safe = DAILY_SALARY * 0.72

    bid = max(bid, min_safe)
    bid = min(bid, budget)
    if budget <= 0:
        return 0.0
    return max(0.0, float(round(bid, 2)))

