def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday trace to infer pressure.
    prev_bids = []
    prev_hp_after = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass
            h = prev.get('hp_after', None)
            if h is not None:
                try:
                    prev_hp_after.append(int(h))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = (sum(prev_bids) / float(len(prev_bids))) if prev_bids else 0.0

    # If opponents were bidding extremely high yesterday, we may need to contest.
    # Otherwise, bid a mid value to avoid wasting budget.
    emergency = (my_hp <= 2) or (my_no_water_days >= 2)

    # Supply pressure proxy: lower supply means higher chance others fight for scarce water.
    # Use a conservative multiplier.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    # supply_ratio in [0,1] ideally; clamp.
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0
    scarcity = 1.0 - supply_ratio  # higher when supply is low

    # Base bid depending on our condition.
    if emergency:
        base = DAILY_SALARY * (0.75 + 0.2 * scarcity)
    else:
        base = DAILY_SALARY * (0.45 + 0.15 * scarcity)

    # Adjust based on yesterday highest bid observed.
    # Bob/Eric were very high yesterday; if highest_prev_bid is high, we bump slightly,
    # but still avoid matching unless we are in emergency.
    if highest_prev_bid >= DAILY_SALARY * 1.5:  # ~120+
        if emergency:
            bid = base * 1.15
        else:
            bid = base * 0.95
    elif highest_prev_bid >= DAILY_SALARY * 1.0:
        bid = base * (1.05 if emergency else 0.98)
    else:
        bid = base * (1.0 if emergency else 0.9)

    # Ensure we never exceed budget.
    bid = min(bid, my_budget)

    # If budget is too low, still bid what we can.
    # Add a small floor to avoid zero when we still need water.
    if my_budget > 0.0 and bid <= 0.0:
        bid = min(my_budget, DAILY_SALARY * 0.2)

    # Final guard: if we are likely to die soon, bid aggressively within budget.
    if my_hp <= 1 and my_budget > 0.0:
        bid = min(my_budget, DAILY_SALARY * 0.95)

    return float(max(0.0, bid))
